parameters.body/messageBody:
{
    "type": "AdaptiveCard",
    "body": [
        {
            "type": "TextBlock",
            "text": "🚨 Azure Alert: @{body('JSON_parseren_1')?['data']?['essentials']?['alertRule']}",
            "weight": "Bolder",
            "size": "Medium",
            "wrap": true
        },
        {
            "type": "TextBlock",
            "text": "Status: @{body('JSON_parseren_1')?['data']?['essentials']?['monitorCondition']}",
            "wrap": true,
            "color": "@{if(equals(body('JSON_parseren_1')?['data']?['essentials']?['monitorCondition'], 'Resolved'), 'Good', 'Attention')}"
        },
        {
            "type": "FactSet",
            "facts": [
                {
                    "title": "Severity",
                    "value": "@{body('JSON_parseren_1')?['data']?['essentials']?['severity']}"
                },
                {
                    "title": "Resource Group",
                    "value": "@{body('JSON_parseren_1')?['data']?['essentials']?['targetResourceGroup']}"
                },
                {
                    "title": "Resource",
                    "value": "@{first(body('JSON_parseren_1')?['data']?['essentials']?['configurationItems'])}"
                },
                {
                    "title": "Description",
                    "value": "@{body('JSON_parseren_1')?['data']?['essentials']?['description']}"
                },
                {
                    "title": "Metric Value",
                    "value": "@{string(body('JSON_parseren_1')?['data']?['alertContext']?['condition']?['allOf']?[0]?['metricValue'])}"
                },
                {
                    "title": "Threshold",
                    "value": "@{body('JSON_parseren_1')?['data']?['alertContext']?['condition']?['allOf']?[0]?['threshold']}"
                },
                {
                    "title": "Fired At",
                    "value": "@{body('JSON_parseren_1')?['data']?['essentials']?['firedDateTime']}"
                },
                {
                    "title": "Resolved At",
                    "value": "@{body('JSON_parseren_1')?['data']?['essentials']?['resolvedDateTime']}"
                }
            ]
        }
    ],
    "actions": [
        {
            "type": "Action.OpenUrl",
            "title": "View in Azure Portal",
            "url": "@{body('JSON_parseren_1')?['data']?['essentials']?['investigationLink']}"
        }
    ],
    "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
    "version": "1.4"
}
